<?php
namespace App\Http\Controllers\Admin; use App\Domain\Faqs\{FaqManager,FaqViewData}; use App\Domain\Installation\WebsiteSettings; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\Faqs\SaveFaqRequest; use App\Models\{Faq,FaqGroup}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Validation\Rule;
class FaqController extends Controller { public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without']]);$q=Faq::with('group')->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('question','like',"%$v%")))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only'){$q->whereNotNull('archived_at');}elseif(($f['archived']??'without')==='without'){$q->whereNull('archived_at');}return view('admin.faqs.index',['items'=>$q->orderBy('display_order')->paginate(20)->withQueryString()]);} public function create():View{return $this->editor(new Faq);} public function store(SaveFaqRequest $r,FaqManager $m):RedirectResponse{$x=$m->save($r->validated(),null,$r->user()->id);return redirect()->route('admin.faqs.edit',$x);} public function edit(Faq $faq):View{return $this->editor($faq);} public function update(SaveFaqRequest $r,Faq $faq,FaqManager $m):RedirectResponse{$m->save($r->validated(),$faq,$r->user()->id);return back()->with('status','Saved.');} private function editor(Faq $item):View{return view('admin.faqs.editor',['item'=>$item,'groups'=>FaqGroup::where('is_active',true)->orderBy('display_order')->get()]);} public function publish(Faq $faq,FaqManager $m):RedirectResponse{$m->publish($faq);return back();} public function schedule(Request $r,Faq $faq,FaqManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($faq,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back();} public function unpublish(Faq $faq,FaqManager $m):RedirectResponse{$m->unpublish($faq);return back();} public function archive(Faq $faq,FaqManager $m):RedirectResponse{$m->archive($faq);return back();} public function restore(Faq $faq,FaqManager $m):RedirectResponse{$m->restore($faq);return back();} public function duplicate(Request $r,Faq $faq,FaqManager $m):RedirectResponse{return redirect()->route('admin.faqs.edit',$m->duplicate($faq,$r->user()->id));} public function move(Faq $faq,string $direction,FaqManager $m):RedirectResponse{$m->move($faq,$direction);return back();} public function preview(Request $r,Faq $faq,FaqViewData $d):Response{return response()->view('faqs.index',['faqs'=>['items'=>[['id'=>$faq->id,'question'=>$faq->question,'answer'=>$faq->answer,'group'=>null]],'schema'=>[]],'preview'=>true]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} public function groups():View{return view('admin.faqs.groups',['items'=>FaqGroup::orderBy('display_order')->get()]);} public function storeFaqGroup(Request $r):RedirectResponse{$d=$r->validate(['title'=>['required','string','max:160'],'slug'=>['required','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/','unique:faq_groups,slug'],'description'=>['nullable','string','max:2000']]);$d['display_order']=(int)FaqGroup::max('display_order')+1;$d['is_active']=true;FaqGroup::create($d);return back();} }
